#include "ff_gui.h"
#include <filesystem>
#include <cstdlib>

namespace fs=std::filesystem;
namespace ff_gui {
static ff::FFConfig defaultConfig(){ff::FFConfig c;c.machineId="FF-001";c.configVersion="FF-CONFIG-1.0";c.maxActiveRodCount=8;for(int i=0;i<3;i++){auto&ch=c.channels[i];ch.id=static_cast<ff::ChannelId>(i);ch.controller.name="CTRL-CH"+std::to_string(i+1);ch.controller.serial.portName="COM"+std::to_string(i+3);ff::RodConfig r;r.id=0;r.name="CH"+std::to_string(i+1)+"-R0";r.hardMin=0;r.hardMax=4095;r.softMin=100;r.softMax=4000;r.zeroPosition=2048;r.safePosition=3900;r.safePositionValid=true;r.maxVelocity=300;r.maxAcceleration=100;r.maxDeceleration=100;r.positionTolerance=5;r.layerMask=1;ch.rods.push_back(r);}return c;}
MainUi::MainUi(){auto root=fs::path(std::getenv("PROGRAMDATA")?std::getenv("PROGRAMDATA"):".")/"RSIC"/"FF";fs::create_directories(root);configPath_=(root/"ff_config.json").string();ensureConfig();}
void MainUi::ensureConfig(){if(!fs::exists(configPath_))ff::FFConfigIO::save(configPath_,defaultConfig());auto x=service_.loadConfig(configPath_,true);configLoaded_=static_cast<bool>(x);if(!x)notice_=x.message;}
void MainUi::draw(){if(!configLoaded_){welcome();return;}dashboard();}
void MainUi::welcome(){ImGui::Text("FF GUI 1.0.0");ImGui::TextWrapped("配置加载失败：%s",notice_.c_str());if(ImGui::Button("重新加载"))ensureConfig();}
void MainUi::dashboard(){auto s=service_.status();ImGui::Text("FF GUI 1.0.0   |   模式: %s",simulation_?"Simulation":"Real");ImGui::SameLine();if(ImGui::Button(service_.connected()?"断开":"连接")){auto x=service_.connected()?service_.disconnect():service_.connect();if(!x)notice_=x.message;}ImGui::SameLine();if(ImGui::Button("刷新状态")){auto x=service_.refresh();if(!x)notice_=x.message;}ImGui::SameLine();if(ImGui::Button("急停"))service_.emergencyStop();ImGui::Separator();if(ImGui::BeginTable("channels",3,ImGuiTableFlags_Borders|ImGuiTableFlags_SizingStretchSame)){for(int i=0;i<3;i++){ImGui::TableNextColumn();drawChannel(i,s);}ImGui::EndTable();}ImGui::SeparatorText("目标与规划");for(auto&r:targets_){int p=r.position;if(ImGui::SliderInt(("CH"+std::to_string(int(r.address.channel)+1)+"/Rod"+std::to_string(r.address.rod)).c_str(),&p,0,4095))r.position=p;}if(targets_.empty()&&service_.connected()){for(int i=0;i<3;i++){auto ch=s.channels[i];for(auto&r:ch.rods)targets_.push_back({{static_cast<ff::ChannelId>(i),0},r.actualPosition,100});}}if(ImGui::Button("预览规划")){auto x=service_.previewPlan({targets_,false});if(x)plan_=x.value;else notice_=x.message;}ImGui::SameLine();ImGui::BeginDisabled(!plan_.valid);if(ImGui::Button("执行规划")){auto x=service_.executePlan(plan_);if(!x)notice_=x.message;}ImGui::EndDisabled();if(plan_.valid)ImGui::Text("规划 #%llu：%s，步骤 %zu",(unsigned long long)plan_.id,plan_.message.c_str(),plan_.steps.size());if(!notice_.empty())ImGui::TextColored(ImVec4(1,0.5f,0.2f,1),"%s",notice_.c_str());}
void MainUi::drawChannel(int index,const ff::FFStatus&s){auto&c=s.channels[index];ImGui::Text("CH%d  %s",index+1,c.connected?"Connected":"Offline");auto&safe=s.safety[index];ImVec4 col=safe.state==ff::SafetyState::Safe?ImVec4(0.2f,0.9f,0.3f,1):ImVec4(1,0.3f,0.2f,1);ImGui::TextColored(col,"Safety: %s",safe.state==ff::SafetyState::Safe?"SAFE":"UNSAFE");for(size_t j=0;j<c.rods.size();j++){auto&r=c.rods[j];ImGui::Text("Rod %d: %d %s",j,r.actualPosition,r.alarm?"ALARM":"");}}
}
